const items = $input.all();
return items.map(item => {
  const body = item.json.body || item.json;

  // 1. Patient identification and complaint
  const patientId = body.patient_id || 'PATIENT_GUEST';
  const rawSpecialty = (body.specialty_type || body.specialty || body.request_type || 'general').toLowerCase();
  const complaint = body.patient_complaint || body.complaint || 'استشارة طبية عامة بدون شكوى مفصلة';
  const imageUrl = body.image_url || body.image_base64 || '';
  const patientContext = body.patient_context || {};

  // 2. Vitals extraction and normalization
  const vitals = patientContext.vitals || {};
  const hr = Number(vitals.heart_rate || vitals.heartRate || 75);
  const sugar = Number(vitals.blood_sugar || vitals.bloodSugar || 98);
  const bpSys = Number(vitals.bp_systolic || vitals.bloodPressureSystolic || 120);
  const bpDia = Number(vitals.bp_diastolic || vitals.bloodPressureDiastolic || 80);
  const temp = Number(vitals.temperature || 37.0);
  const spo2 = Number(vitals.spo2 || 98);
  const weight = Number(vitals.weight || 70.0);

  // 3. Clinical Danger Evaluation Matrix
  const dangerFlags = [];
  if (bpSys >= 180 || bpDia >= 110) dangerFlags.push('أزمة فرط ضغط دم حادة (BP >= 180/110 mmHg)');
  if (sugar < 55) dangerFlags.push('هبوط سكر حاد مهدد للوعي (Sugar < 55 mg/dL)');
  if (sugar > 300) dangerFlags.push('ارتفاع سكر حرج وخطر حموضة كيتونية (Sugar > 300 mg/dL)');
  if (hr > 140) dangerFlags.push('تسارع نبض شديد (HR > 140 bpm)');
  if (hr < 45) dangerFlags.push('بطء نبض شديد (HR < 45 bpm)');
  if (spo2 < 90) dangerFlags.push('نقص أكسجين حاد يستوجب دعم تنفسي (SpO2 < 90%)');

  const isEmergency = dangerFlags.length > 0;
  const emergencyBanner = isEmergency 
    ? `🚨 تحذير سريري حرج: رصدت خوارزميات عون علامات خطر حيوية تستوجب التقييم الإسعافي الفوري: [${dangerFlags.join(' | ')}]` 
    : null;

  // 4. Clinical Route Index (0: Derm, 1: Chest, 2: Dental, 3: Lab, 4: General)
  let routeIndex = 4;
  let normalizedSpecialty = 'general';

  if (rawSpecialty.includes('derm') || rawSpecialty.includes('skin') || rawSpecialty.includes('جلد')) {
    routeIndex = 0;
    normalizedSpecialty = 'dermatology';
  } else if (rawSpecialty.includes('chest') || rawSpecialty.includes('xray') || rawSpecialty.includes('صدر') || rawSpecialty.includes('رئة') || rawSpecialty.includes('تنفس')) {
    routeIndex = 1;
    normalizedSpecialty = 'chest';
  } else if (rawSpecialty.includes('dent') || rawSpecialty.includes('teeth') || rawSpecialty.includes('اسنان') || rawSpecialty.includes('لثة')) {
    routeIndex = 2;
    normalizedSpecialty = 'dental';
  } else if (rawSpecialty.includes('lab') || rawSpecialty.includes('blood') || rawSpecialty.includes('تحليل') || rawSpecialty.includes('مختبر') || rawSpecialty.includes('تقرير')) {
    routeIndex = 3;
    normalizedSpecialty = 'lab_analyzer';
  }

  return {
    json: {
      patient_id: patientId,
      specialty: normalizedSpecialty,
      route_index: routeIndex,
      complaint: complaint,
      image_url: imageUrl,
      patient_context: patientContext,
      vitals: { hr, sugar, bpSys, bpDia, temp, spo2, weight },
      is_emergency: isEmergency,
      emergency_flags: dangerFlags,
      emergency_alert: emergencyBanner,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
const parserNode = $('Clinical Data Parser & Risk Engine').first().json;

return items.map(item => {
  const json = item.json;

  // Extract AI text from Gemini output
  let aiText = '';
  if (json.content && json.content.parts && json.content.parts.length > 0) {
    aiText = json.content.parts.map(p => p.text || '').join('\n');
  } else if (json.text) {
    aiText = json.text;
  } else if (json.response) {
    aiText = json.response;
  } else if (typeof json === 'string') {
    aiText = json;
  } else {
    aiText = JSON.stringify(json);
  }

  // Format standardized dual-head payload expected by Flutter ChatService
  const responsePayload = {
    status: 'success',
    patient_id: parserNode.patient_id,
    specialty: parserNode.specialty,
    gemini_diagnostic_response: aiText,
    ai_vision_findings: parserNode.image_url 
      ? `تم فحص وتحليل الصورة الإشعاعية/السريرية المرفقة لتخصص [${parserNode.specialty}] بنجاح ومطابقتها مع المعايير الطبية المعتمدة.`
      : 'استشارة سريرية نصية - لم يتم إرفاق صورة فحص طبي.',
    is_emergency: parserNode.is_emergency,
    emergency_alert: parserNode.emergency_alert,
    vitals_snapshot: parserNode.vitals,
    consultation_timestamp: new Date().toISOString(),
    ai_model: 'AWN Clinical Intelligence Engine',
    disclaimer: 'تطبيق عون يقدم انطباعات توجيهية استرشادية ولا يُعد تشخيصاً نهائياً بديلاً عن الفحص الطبي المباشر.'
  };

  return { json: responsePayload };
});
